        assert!(!has_id(&diags, "QUIT"), "got: {diags:?}");
    }

    #[test]
    fn quit_does_not_fire_on_incomplete_tail() {
        let diags = lint_file(&*engine(), "x = 1; 2");
        assert!(!has_id(&diags, "QUIT"), "got: {diags:?}");
