    pub(crate) fn check_mcfil(
        &self,
        class: &ClassMeta,
        ctx: &FileContext,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        let file_stem = ctx
            .file_path
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or("");
        if !file_stem.is_empty() && file_stem != class.name {
            // Don't fire if the file is in a @directory (MCDIR handles that)
            let in_at_dir = ctx
                .file_path
                .parent()
