                .and_then(|n| n.to_str())
                .is_some_and(|dir| dir.starts_with('@'));
            if !in_at_dir {
                diagnostics.push(Diagnostic {
                    rule_id: "MCFIL",
                    message: format!(
                        "Class name '{}' does not match file name '{}'",
                        class.name, file_stem
                    ),
                    severity: Severity::Error,
                    byte_range: class.byte_range.clone(),
                    line: class.line,
                    column: 1,
                    fix: None,
