import json, re, glob

dirs = ["crates/mlt_rules/src/language_spec", "crates/mlt_rules/src/incomplete_analysis"]

raw = ""
for d in dirs:
    for f in glob.glob(d + "/*.rs"):
        for ln in open(f).read().split('\n'):
            s = ln.lstrip()
            if s.startswith('//') or s.startswith('*'):
                continue
            raw += ln + "\n"
# unescape rust string-literal backslash-quote so "who"/"whos" matches
raw = re.sub(r'\\"', '"', raw)
raw = re.sub(r'\\\n\s*', ' ', raw)
raw = re.sub(r'\s+', ' ', raw)

def build_regex(mw):
    parts = re.split(r'(VAR_[A-Z_]+)', mw)
    rx = ""
    for p in parts:
        if re.fullmatch(r'VAR_[A-Z_]+', p):
            rx += r'[^"]*'
        else:
            rx += re.escape(p)
    return re.compile(rx)

problems = []
for fn in ["language_spec", "incomplete_analysis"]:
    for e in json.load(open(f".playwright-mcp/targets/{fn}.json")):
        mw = e["mw"]
        if not mw:
            continue
        if e["id"] == "SPBRK":
            continue  # no code emits it (subsumed by SPRET)
        if e["id"] == "QUIT":
            continue  # in mlt_core, already correct
        rx = build_regex(mw)
        if not rx.search(raw):
            problems.append((fn, e["id"], mw))

print("Remaining mismatches:")
for p in problems:
    print(p)
print("total:", len(problems))
